<template><div><div class="d-flex flex-wrap align-end justify-space-between ga-4 mb-6"><div><div class="eyebrow mb-2">Administration</div><h1 class="page-heading">Benutzerverwaltung</h1><p class="muted mt-2">Konten, Rollen und Zugänge zentral steuern.</p></div><v-btn color="primary" prepend-icon="mdi-account-plus-outline" size="large" @click="openCreate">Benutzer anlegen</v-btn></div><v-card class="surface-card overflow-hidden"><v-skeleton-loader v-if="loading" type="table-heading,table-row@5"/><v-table v-else><thead><tr><th>Benutzer</th><th>Rollen</th><th>Status</th><th>Erstellt</th><th></th></tr></thead><tbody><tr v-for="user in users" :key="user.id"><td><strong>{{user.name}}</strong><div class="text-caption muted">{{user.email}}</div></td><td><v-chip v-for="entry in user.roles" :key="entry.id" size="small" class="mr-1" variant="tonal">{{entry.role.name}}</v-chip></td><td><v-chip size="small" :color="user.isActive?'success':'grey'" variant="tonal">{{user.isActive?'Aktiv':'Deaktiviert'}}</v-chip></td><td>{{date(user.createdAt)}}</td><td class="text-right"><v-btn icon="mdi-pencil-outline" variant="text" @click="openEdit(user)"/></td></tr></tbody></v-table></v-card><v-dialog v-model="dialog" max-width="560"><v-card class="pa-6"><h2 class="text-h5 font-weight-bold mb-5">{{editing?'Benutzer bearbeiten':'Benutzer anlegen'}}</h2><v-form ref="formRef" @submit.prevent="save"><v-text-field v-model="form.name" label="Name" :rules="[required]"/><v-text-field v-model="form.email" label="E-Mail" type="email" :disabled="Boolean(editing)" :rules="[required]"/><v-text-field v-if="!editing" v-model="form.password" label="Initiales Passwort" type="password" hint="Mindestens 12 Zeichen" persistent-hint :rules="[passwordRule]"/><v-select v-model="form.roleNames" label="Rollen" :items="['Benutzer','Administrator']" multiple chips :rules="[rolesRule]"/><v-switch v-if="editing" v-model="form.isActive" label="Konto aktiv" color="success"/><div class="d-flex justify-end ga-3 mt-4"><v-btn variant="text" @click="dialog=false">Abbrechen</v-btn><v-btn color="primary" type="submit" :loading="saving">Speichern</v-btn></div></v-form></v-card></v-dialog></div></template>
<script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{api,apiMessage}from'../api/client';import{useUiStore}from'../stores/ui';interface User{id:string;name:string;email:string;isActive:boolean;createdAt:string;roles:Array<{id:string;role:{name:string}}>}const users=ref<User[]>([]),loading=ref(true),dialog=ref(false),saving=ref(false),editing=ref<User|null>(null),ui=useUiStore(),formRef=ref<{validate():Promise<{valid:boolean}>}>();const form=reactive({name:'',email:'',password:'',roleNames:['Benutzer'],isActive:true});const required=(v:unknown)=>Boolean(String(v??'').trim())||'Pflichtfeld',passwordRule=(v:string)=>v.length>=12||'Mindestens 12 Zeichen',rolesRule=(v:string[])=>v.length>0||'Mindestens eine Rolle';async function load(){loading.value=true;try{users.value=(await api.get('/users')).data}catch(e){ui.notify(apiMessage(e),'error')}finally{loading.value=false}}function openCreate(){editing.value=null;Object.assign(form,{name:'',email:'',password:'',roleNames:['Benutzer'],isActive:true});dialog.value=true}function openEdit(u:User){editing.value=u;Object.assign(form,{name:u.name,email:u.email,password:'',roleNames:u.roles.map(x=>x.role.name),isActive:u.isActive});dialog.value=true}async function save(){const v=await formRef.value?.validate();if(!v?.valid)return;saving.value=true;try{editing.value?await api.patch(`/users/${editing.value.id}`,{name:form.name,roleNames:form.roleNames,isActive:form.isActive}):await api.post('/users',form);ui.notify(editing.value?'Benutzer aktualisiert.':'Benutzer angelegt.');dialog.value=false;await load()}catch(e){ui.notify(apiMessage(e),'error')}finally{saving.value=false}}function date(v:string){return new Intl.DateTimeFormat('de-DE').format(new Date(v))}onMounted(load);</script>
